CREATE TABLE provinces (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, region ENUM('XSMB','XSMT','XSMN') NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, INDEX idx_province_region (region)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sources (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, base_url VARCHAR(255) NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE lottery_draws (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, region ENUM('XSMB','XSMT','XSMN') NOT NULL, province VARCHAR(100) NOT NULL, draw_date DATE NOT NULL, source VARCHAR(255) NOT NULL, fetched_at DATETIME NOT NULL, checksum CHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_draw (region, province, draw_date), INDEX idx_draw_date (draw_date), INDEX idx_region (region), INDEX idx_province (province)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE lottery_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, draw_id BIGINT UNSIGNED NOT NULL, prize VARCHAR(16) NOT NULL, position SMALLINT UNSIGNED NOT NULL, number VARCHAR(6) NOT NULL, UNIQUE KEY uq_result (draw_id, prize, position), INDEX idx_result_draw (draw_id), CONSTRAINT fk_result_draw FOREIGN KEY (draw_id) REFERENCES lottery_draws(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE source_health (source VARCHAR(100) PRIMARY KEY, success_count INT UNSIGNED NOT NULL DEFAULT 0, failure_count INT UNSIGNED NOT NULL DEFAULT 0, average_response_time DECIMAL(10,2) NOT NULL DEFAULT 0, last_success DATETIME NULL, last_failure DATETIME NULL, last_error VARCHAR(255) NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sync_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_id VARCHAR(32) NOT NULL, source VARCHAR(100) NOT NULL, operation VARCHAR(50) NOT NULL, status VARCHAR(30) NOT NULL, duration_ms INT UNSIGNED NOT NULL, details VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_sync_created (created_at), INDEX idx_sync_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE rate_limits (rate_key CHAR(64) PRIMARY KEY, hits INT UNSIGNED NOT NULL, window_started DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
